	await persistTokens({
		accessToken: json.access_token,
		refreshToken: json.refresh_token ?? null,
		expiresAt: new Date(Date.now() + Math.max(60, json.expires_in ?? 3600) * 1e3).toISOString(),
		email,
		tokenType: json.token_type ?? "Bearer"
	});
